import { registerHooks } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
const variant = process.env.AUDIT_IMPACT_VARIANT;
if (!['before', 'after'].includes(variant)) throw Error('An audit runtime variant is required');
const overrides = JSON.parse(readFileSync(new URL(`./${variant}-overrides.json`, import.meta.url), 'utf8'));
const loaded = [];
if (process.env.AUDIT_IMPACT_COVERAGE_OUTPUT) {
  const { Session } = await import('node:inspector');
  const session = new Session(); session.connect();
  const post = (method, params = {}) => new Promise((resolve, reject) => session.post(method, params, (error, result) => error ? reject(error) : resolve(result)));
  await post('Profiler.enable'); await post('Profiler.startPreciseCoverage', { callCount: true, detailed: true });
  globalThis.captureAuditCoverage = async label => {
    const coverage = await post('Profiler.takePreciseCoverage');
    const selected = coverage.result.filter(entry => Object.hasOwn(overrides, entry.url) || entry.url.endsWith('/after/server-entry.js'));
    writeFileSync(`${process.env.AUDIT_IMPACT_COVERAGE_OUTPUT}-${label}.json`, JSON.stringify(selected));
  };
}
registerHooks({
  load(url, context, nextLoad) {
    if (Object.hasOwn(overrides, url)) { loaded.push(url); return { format: 'module', source: overrides[url], shortCircuit: true }; }
    const result = nextLoad(url, context);
    if (process.env.AUDIT_IMPACT_COVERAGE_OUTPUT && url.endsWith('/framework-comparison/src/ssr-benchmark-worker.mjs')) {
      result.source = result.source.toString().replace('resetTelemetry();', "await globalThis.captureAuditCoverage('startup'); resetTelemetry();").replace('async function shutdown(reason) {', "async function shutdown(reason) { await globalThis.captureAuditCoverage('requests');");
    }
    return result;
  }
});
process.on('exit', () => {
  if (process.env.AUDIT_IMPACT_LOAD_REPORT) writeFileSync(process.env.AUDIT_IMPACT_LOAD_REPORT, JSON.stringify({ variant, loaded }));
});

